/* Jua (SIL Open Font License, fonts/OFL.txt), cut down to the letters the app shows.
   Made by scripts/build.py font. */
(function () {
  try {
    const bytes = Uint8Array.from(atob(''), (c) => c.charCodeAt(0));
    document.fonts.add(new FontFace('Jua', bytes));
  } catch (e) { /* the phone's own font shows instead */ }
})();
